        }
        .width('100%')
        .height(180)
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
        .backgroundColor(this.maskColor)
        .borderRadius(12)
      }
      .width('100%')
      .height(180)

      Row() {
        Text('遮罩浓度')
          .width(60)
          .fontSize(12)
        Slider({ value: this.maskOpacity, min: 0, max: 100, step: 1 })
          .layoutWeight(1)
          .onChange((v: number) => {
            this.maskOpacity = v
            const alpha = Math.round(v * 2.55)
            this.maskColor = (alpha << 24) | color
          })
        Text(`${this.maskOpacity}%`)
          .width(50)
          .fontSize(11)
          .textAlign(TextAlign.End)
      }
      Row({ space: 8 }) {
        Button('黑色遮罩')
          .fontSize(12)
          .backgroundColor(0x666666)
          .onClick(() => { this.maskColor = 0x66000000 })
        Button('蓝色遮罩')
          .fontSize(12)
          .backgroundColor(0x666666)
          .onClick(() => { this.maskColor = 0x66007DFF })
        Button('清除遮罩')
          .fontSize(12)
          .backgroundColor(0x666666)
          .onClick(() => { this.maskColor = 0x00000000 })
      }
    }
    .width('100%')
    .padding(14)
    .backgroundColor(this.cardBg)
    .borderRadius(12)
    .alignItems(HorizontalAlign.Start)
